package system_test

import (
	"testing"

	"software-studio/internal/system"
)

// These fixtures are handwritten observations, independent of the model and
// implementation adapters. Expected outcomes must not be generated by either.
func TestIndependentContractAcceptance(t *testing.T) {
	contract := system.Contract{ID: "acceptance", Revision: "1", Claims: []system.Claim{
		{ID: "unique", Kind: "exactly_one_record"},
		{ID: "backed", Kind: "no_false_success"},
		{ID: "coverage", Kind: "required_evidence"},
	}}
	cases := []struct {
		name   string
		events []system.Event
		want   map[string]string
	}{
		{"idempotent replay", []system.Event{
			{Sequence: 1, Kind: "request_received", RequestID: "a"},
			{Sequence: 2, Kind: "persisted", RequestID: "a", EncounterID: "one"},
			{Sequence: 3, Kind: "response_success", RequestID: "a", EncounterID: "one"},
			{Sequence: 4, Kind: "request_received", RequestID: "a"},
			{Sequence: 5, Kind: "persisted", RequestID: "a", EncounterID: "one"},
			{Sequence: 6, Kind: "response_success", RequestID: "a", EncounterID: "one"},
		}, map[string]string{"unique": "satisfied", "backed": "satisfied", "coverage": "satisfied"}},
		{"duplicate despite later telemetry gap", []system.Event{
			{Sequence: 1, Kind: "request_received", RequestID: "a"},
			{Sequence: 2, Kind: "persisted", RequestID: "a", EncounterID: "one"},
			{Sequence: 3, Kind: "persisted", RequestID: "a", EncounterID: "two"},
			{Sequence: 4, Kind: "evidence_gap", RequestID: "a"},
		}, map[string]string{"unique": "violated", "coverage": "inconclusive"}},
		{"silent run", nil, map[string]string{"unique": "inconclusive", "backed": "inconclusive", "coverage": "inconclusive"}},
		{"success before persistence", []system.Event{
			{Sequence: 1, Kind: "request_received", RequestID: "a"},
			{Sequence: 2, Kind: "response_success", RequestID: "a", EncounterID: "one"},
			{Sequence: 3, Kind: "persisted", RequestID: "a", EncounterID: "one"},
		}, map[string]string{"backed": "violated"}},
		{"other request cannot justify success", []system.Event{
			{Sequence: 1, Kind: "request_received", RequestID: "a"},
			{Sequence: 2, Kind: "persisted", RequestID: "a", EncounterID: "one"},
			{Sequence: 3, Kind: "response_success", RequestID: "a", EncounterID: "one"},
			{Sequence: 4, Kind: "request_received", RequestID: "b"},
			{Sequence: 5, Kind: "response_success", RequestID: "b", EncounterID: "one"},
		}, map[string]string{"backed": "violated"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := map[string]string{}
			for _, verdict := range system.Evaluate(contract, tc.events) {
				got[verdict.ClaimID] = verdict.Status
			}
			for claim, want := range tc.want {
				if got[claim] != want {
					t.Errorf("claim %s: got %q, want %q", claim, got[claim], want)
				}
			}
		})
	}
}
